-- Title: catalog price band calculation modes schema
-- Kind: patch
-- Intent: catalog_price_band_calculation_modes
-- Context: TH-02 / EPIC-06 — persist one exclusive calculation source per product-unit price band
-- Touches: _recalculate_product_price_bands
-- Safety: idempotent ; medium
-- Depends on: 20260714008_catalog_patch_scale_unit_base_price_by_conversion_rate.sql
-- Promoted from _drafts/catalog_price_band_calculation_modes_schema.sql
-- Generated by tools/c45_supabase_migrate/bin/promote_drafts.dart

do $$
begin
  if not exists (
    select 1
    from pg_type t
    join pg_namespace n on n.oid = t.typnamespace
    where n.nspname = 'catalog'
      and t.typname = 'price_band_source_type'
  ) then
    create type catalog.price_band_source_type as enum ('ruleBased', 'customConfig', 'manual');
  end if;
end;
$$;

alter table catalog.product_unit_price_bands
  add column if not exists list_markup_ratio numeric null,
  add column if not exists floor_markup_ratio numeric null;

-- Legacy manual rows remain manual. Do not infer a ratio from rounded prices.
update catalog.product_unit_price_bands
set list_markup_ratio = null,
    floor_markup_ratio = null,
    is_custom_override = false
where source_type in ('manual', 'ruleBased');

alter table catalog.product_unit_price_bands
  drop constraint if exists product_unit_price_bands_source_type_check,
  drop constraint if exists product_unit_price_bands_calculation_source_check,
  drop constraint if exists product_unit_price_bands_markup_ratio_check;

do $$
declare
  v_invalid_source_type text;
begin
  select pb.source_type::text
  into v_invalid_source_type
  from catalog.product_unit_price_bands pb
  where pb.source_type::text not in ('ruleBased', 'customConfig', 'manual')
  limit 1;

  if v_invalid_source_type is not null then
    raise exception 'invalid product_unit_price_bands.source_type: %',
      v_invalid_source_type;
  end if;
end;
$$;

alter table catalog.product_unit_price_bands
  alter column source_type drop default;

alter table catalog.product_unit_price_bands
  alter column source_type type catalog.price_band_source_type
    using source_type::text::catalog.price_band_source_type;

alter table catalog.product_unit_price_bands
  alter column source_type set default 'manual'::catalog.price_band_source_type;

alter table catalog.product_unit_price_bands
  add constraint product_unit_price_bands_markup_ratio_check
    check (
      list_markup_ratio is null or list_markup_ratio >= 0
    ) not valid,
  add constraint product_unit_price_bands_calculation_source_check
    check (
      (source_type = 'ruleBased'
        and store_price_rule_id is not null
        and list_markup_ratio is null
        and floor_markup_ratio is null)
      or
      (source_type = 'customConfig'
        and store_price_rule_id is null
        and list_markup_ratio is not null
        and list_markup_ratio >= 0
        and (floor_markup_ratio is null or (
          floor_markup_ratio >= 0
          and floor_markup_ratio <= list_markup_ratio
        )))
      or
      (source_type = 'manual'
        and store_price_rule_id is null
        and list_markup_ratio is null
        and floor_markup_ratio is null)
    ) not valid;

alter table catalog.product_unit_price_bands
  validate constraint product_unit_price_bands_markup_ratio_check;

comment on column catalog.product_unit_price_bands.list_markup_ratio is
  'Decimal markup ratio owned by a customConfig band; 0.40 means 40 percent.';
comment on column catalog.product_unit_price_bands.floor_markup_ratio is
  'Optional decimal floor markup ratio owned by a customConfig band.';
comment on column catalog.product_unit_price_bands.source_type is
  'Exclusive price calculation source: ruleBased, customConfig, or manual.';

create or replace function catalog._recalculate_product_price_bands(
  p_tenant_id uuid,
  p_product_id uuid default null,
  p_store_price_rule_id uuid default null
)
returns integer
language plpgsql
security definer
set search_path = catalog, pg_temp
as $$
declare
  v_updated integer;
begin
  with recalculated as (
    select
      pb.id,
      round(
        bp.base_price_after_vat * pu.conversion_rate_to_base
        * (1 + case
          when pb.source_type = 'customConfig' then pb.list_markup_ratio
          else sr.list_markup_ratio
        end)
      ) as list_price,
      case
        when case
          when pb.source_type = 'customConfig' then pb.floor_markup_ratio
          else sr.floor_markup_ratio
        end is null then null
        else round(
          bp.base_price_after_vat * pu.conversion_rate_to_base
          * (1 + case
            when pb.source_type = 'customConfig' then pb.floor_markup_ratio
            else sr.floor_markup_ratio
          end)
        )
      end as floor_price
    from catalog.product_unit_price_bands pb
    join catalog.product_units pu
      on pu.id = pb.product_unit_id
     and pu.product_id = pb.product_id
     and pu.tenant_id = pb.tenant_id
    join catalog.product_base_price_profiles bp
      on bp.product_id = pb.product_id
     and bp.tenant_id = pb.tenant_id
    left join catalog.store_price_rules sr
      on sr.id = pb.store_price_rule_id
     and sr.tenant_id = pb.tenant_id
     and sr.status = 'active'
    where pb.tenant_id = p_tenant_id
      and pb.status = 'active'
      and pu.is_active = true
      and pu.conversion_rate_to_base > 0
      and bp.base_price_after_vat is not null
      and (p_product_id is null or pb.product_id = p_product_id)
      and (
        (pb.source_type = 'customConfig' and p_store_price_rule_id is null)
        or
        (pb.source_type = 'ruleBased'
          and sr.id is not null
          and (p_store_price_rule_id is null or sr.id = p_store_price_rule_id))
      )
  )
  update catalog.product_unit_price_bands pb
  set list_price_before_vat = r.list_price,
      floor_price_before_vat = r.floor_price,
      list_price_after_vat = r.list_price,
      floor_price_after_vat = r.floor_price,
      updated_at = now()
  from recalculated r
  where pb.id = r.id;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;

revoke all on function catalog._recalculate_product_price_bands(uuid, uuid, uuid)
  from public, anon, authenticated;
grant execute on function catalog._recalculate_product_price_bands(uuid, uuid, uuid)
  to service_role;
